use serde::{Deserialize, Serialize};

/// Track metadata generated by AI (FAZA 2 Extended - B1-B11)
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TrackMetadataAI {
    pub genre: String,
    pub sub_genre: Option<String>,
    pub mood: String,
    pub energy_level: u8,      // 1-10
    pub tempo: String,         // slow, medium, fast
    pub danceability: u8,      // 1-10 (B7)
    pub vocal_type: String,    // instrumental, female vocals, male vocals, mixed vocals, rap, choir (B8)
    pub decade: String,        // 1960s, 1970s, 1980s, 1990s, 2000s, 2010s, 2020s (B9)
    pub language: String,      // English, Romanian, Spanish, French, Instrumental, etc. (B10)
    pub activity_tags: Vec<String>,  // workout, study, sleep, driving, party, cooking, meditation (B11)
    pub occasion_tags: Vec<String>,  // wedding, birthday, christmas, summer, road trip (B11)
    pub keywords: Vec<String>,
}

/// Smart playlist suggestion
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PlaylistSuggestion {
    pub name: String,
    pub description: String,
    pub search_queries: Vec<String>,
}

/// Parsed natural language command
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "command")]
pub enum PlayerCommand {
    #[serde(rename = "play")]
    Play { query: Option<String> },
    #[serde(rename = "pause")]
    Pause,
    #[serde(rename = "next")]
    Next,
    #[serde(rename = "previous")]
    Previous,
    #[serde(rename = "favorite")]
    AddToFavorites,
    #[serde(rename = "search")]
    Search { query: String },
    #[serde(rename = "create_playlist")]
    CreatePlaylist { name: String, description: Option<String> },
    #[serde(rename = "set_mood")]
    SetMood { mood: String },
    #[serde(rename = "set_volume")]
    SetVolume { level: f32 },
    #[serde(rename = "add_to_queue")]
    AddToQueue { query: String },
    #[serde(rename = "toggle_shuffle")]
    ToggleShuffle,
    #[serde(rename = "set_repeat")]
    SetRepeat { mode: String },
    #[serde(rename = "navigate")]
    Navigate { view: String },
    #[serde(rename = "download")]
    Download { query: Option<String> },
    #[serde(rename = "multi")]
    MultiCommand { commands: Vec<PlayerCommand> },
    #[serde(rename = "unknown")]
    Unknown,
}

