    /// Generate a smart playlist plan from description, mood, or activity
    pub fn smart_playlist_plan(
        description: &str,
        method: &str,
        duration_minutes: Option<u32>,
        library_genres: &[String],
        library_moods: &[String],
    ) -> String {
        let duration_hint = duration_minutes
            .map(|d| format!("\nTarget duration: approximately {} minutes.", d))
            .unwrap_or_default();

        let library_context = if library_genres.is_empty() && library_moods.is_empty() {
            String::new()
        } else {
            format!(
                "\nUser's library contains these genres: [{}]\nUser's library contains these moods: [{}]",
                library_genres.join(", "),
                library_moods.join(", ")
            )
        };

        let method_instruction = match method {
            "mood" => format!(
                "The user wants a playlist matching this mood/feeling: \"{}\".\nFocus on mood-appropriate genres, tempos, and energy levels.",
                description
            ),
            "activity" => format!(
                "The user wants a playlist for this activity: \"{}\".\nChoose tempo, energy, and genre appropriate for the activity.",
                description
            ),
            _ => format!(
                "The user described their desired playlist as: \"{}\"",
                description
            ),
        };

        format!(
            r#"You are a music curator AI. Create a smart playlist plan.

{}{}{}

Generate a structured plan with:
1. A catchy playlist name
2. A short description (1-2 sentences)
3. Filtering criteria to match existing library tracks
4. 5-10 YouTube search queries to find additional tracks

IMPORTANT: For genres, moods, decades, activities - use lowercase values.
For energy_min and energy_max use 1-10 scale.
For tempo use: "slow", "medium", "fast", or null if any tempo is fine.

Return JSON:
{{
  "name": "Playlist Name",
  "description": "Short description",
  "genres": ["rock", "metal"],
  "moods": ["energetic", "aggressive"],
  "energy_min": 6,
  "energy_max": 10,
  "decades": ["1980s", "1990s"],
  "tempo": "fast",
  "activities": ["workout", "driving"],
  "search_queries": ["AC/DC Thunderstruck", "Metallica Enter Sandman", ...]
}}"#,
            method_instruction, duration_hint, library_context
        )
    }

    /// Generate a "more like this" playlist plan from a seed track
    pub fn seed_track_playlist(
        title: &str,
        artist: &str,
        genre: Option<&str>,
        mood: Option<&str>,
        energy: Option<i32>,
        decade: Option<&str>,
    ) -> String {
        let metadata_context = {
            let mut parts = Vec::new();
            if let Some(g) = genre { parts.push(format!("Genre: {}", g)); }
            if let Some(m) = mood { parts.push(format!("Mood: {}", m)); }
            if let Some(e) = energy { parts.push(format!("Energy: {}/10", e)); }
            if let Some(d) = decade { parts.push(format!("Decade: {}", d)); }
            if parts.is_empty() {
                String::new()
            } else {
                format!("\nKnown metadata: {}", parts.join(", "))
            }
        };

        format!(
            r#"You are a music curator AI. Create a "More Like This" playlist plan.

Seed track: "{}" by {}{}

Generate a playlist of similar tracks. Consider:
- Same or adjacent genres
- Similar mood and energy level
- Same era/decade or timeless classics
- Similar artists or musical style

Return JSON:
{{
  "name": "Playlist Name",
  "description": "Short description",
  "genres": ["genre1", "genre2"],
  "moods": ["mood1"],
  "energy_min": 5,
  "energy_max": 8,
  "decades": ["1980s", "1990s"],
  "tempo": null,
  "activities": [],
  "search_queries": ["Artist - Song", "Another Artist - Song", ...]
}}"#,
            title, artist, metadata_context
        )
    }

