    /// C6: Generate a Daily Mix playlist based on listening history and time context
    pub fn daily_mix(
        library_summary: &str,
        recent_tracks: &str,
        hour: u32,
        day_of_week: &str,
        top_genres: &[String],
        top_moods: &[String],
    ) -> String {
        let time_context = match hour {
            5..=8 => "Early morning — gentle, calm music to start the day",
            9..=11 => "Morning — upbeat, productive energy",
            12..=13 => "Lunchtime — relaxed, moderate energy",
            14..=16 => "Afternoon — focused, steady energy",
            17..=19 => "Evening — transitioning from work, mixed energy",
            20..=22 => "Night — relaxed or social vibe",
            _ => "Late night — calm, ambient, winding down",
        };

        let weekend_hint = match day_of_week {
            "Saturday" | "Sunday" => "\nIt's the weekend — user might want relaxed or party vibes.",
            "Friday" => "\nIt's Friday — user might want upbeat/celebratory music.",
            _ => "",
        };

        let genres_context = if top_genres.is_empty() {
            "Not enough data yet".to_string()
        } else {
            top_genres.join(", ")
        };

        let moods_context = if top_moods.is_empty() {
            "Not enough data yet".to_string()
        } else {
            top_moods.join(", ")
        };

        format!(
            r#"You are a personal DJ AI creating a \"Daily Mix\" playlist.

Current context:
- Time: {}:00 ({})
- Day: {}{}
- User's top genres: {}
- User's top moods: {}

Recently played (for variety — avoid repeating these):
{}

Available library tracks (id | title | artist | genre | mood | energy):
{}

Create a personalized Daily Mix of 10-15 tracks that:
1. Matches the time-of-day context
2. Reflects the user's top genres and moods
3. Avoids recently played tracks
4. Starts with a strong opener that fits the vibe
5. Has good flow — energy transitions should be smooth
6. Mixes favorites with less-played tracks for discovery

Also generate a catchy name and description for today's mix.

Return JSON:
{{
  "name": "Daily Mix — descriptive theme",
  "description": "Short 1-sentence description of today's vibe",
  "track_ids": ["id1", "id2", ...]
}}"#,
            hour, time_context, day_of_week, weekend_hint,
            genres_context, moods_context, recent_tracks, library_summary
        )
    }

