    /// D2: Disambiguate track — when multiple YouTube results look similar
    pub fn disambiguate_track(
        title: &str,
        artist: &str,
        album: &str,
        results: &[(String, String, String, Option<i64>)], // (id, title, channel, duration)
    ) -> String {
        let results_text: String = results
            .iter()
            .enumerate()
            .map(|(i, (id, yt_title, channel, dur))| {
                let dur_str = dur
                    .map(|d| format!(" [{}:{:02}]", d / 60, d % 60))
                    .unwrap_or_default();
                format!("{}. ID:{} | \"{}\" | Canal: {}{}", i + 1, id, yt_title, channel, dur_str)
            })
            .collect::<Vec<_>>()
            .join("\n");

        format!(
            r#"Ai de dezambiguizat rezultatele YouTube pentru o piesă Spotify.

Track Spotify:
- Titlu: "{}"
- Artist: "{}"
- Album: "{}"

Rezultate YouTube (toate par similare):
{}

Decide care rezultat este versiunea originală/oficială a piesei. Prioritizează:
1. Audio oficial / canalul oficial al artistului / VEVO
2. Versiunea de studio (nu live, nu cover, nu remix)
3. Calitate audio bună (preferă "official audio" vs "lyric video" vs "music video")
4. Durată corespunzătoare (versiunile de studio au durată standard)

Returnează JSON:
{{
  "selected_id": "id-ul YouTube ales",
  "confidence": "high" | "medium" | "low",
  "reason": "explicație scurtă de ce ai ales acest rezultat",
  "is_cover": false,
  "is_live": false,
  "is_remix": false
}}"#,
            title, artist, album, results_text
        )
    }

    /// D3: Alternative search queries when primary search fails
    pub fn alternative_queries(
        track_name: &str,
        artist_name: &str,
        album: &str,
    ) -> String {
        format!(
            r#"Piesa Spotify nu a fost găsită pe YouTube cu căutarea standard.

Track:
- Titlu: "{}"
- Artist: "{}"
- Album: "{}"

Generează 5 căutări alternative YouTube care ar putea găsi această piesă:
1. Variante ale numelui (cu/fără caractere speciale, prescurtări)
2. Căutare doar după artist + cuvinte cheie din titlu
3. Căutare cu "official audio" sau "lyrics"
4. Căutare cu numele albumului
5. Transliterare/traducere dacă titlul e în altă limbă

Returnează JSON:
{{
  "queries": ["query1", "query2", "query3", "query4", "query5"],
  "likely_issue": "explicație de ce căutarea standard a eșuat (ex: caractere speciale, titlu ambiguu, artist obscur)",
  "suggestion": "sugestie pentru utilizator dacă nimic nu funcționează"
}}"#,
            track_name, artist_name, album
        )
    }

    /// D4: Assess match quality between Spotify track and YouTube result
    pub fn assess_match_quality(
        spotify_title: &str,
        spotify_artist: &str,
        spotify_album: &str,
        spotify_duration_sec: Option<i64>,
        youtube_title: &str,
        youtube_channel: &str,
        youtube_duration_sec: Option<i64>,
    ) -> String {
        let sp_dur = spotify_duration_sec
            .map(|d| format!("{}:{:02}", d / 60, d % 60))
            .unwrap_or("necunoscut".to_string());
        let yt_dur = youtube_duration_sec
            .map(|d| format!("{}:{:02}", d / 60, d % 60))
            .unwrap_or("necunoscut".to_string());

        format!(
            r#"Evaluează calitatea match-ului dintre o piesă Spotify și un rezultat YouTube.

Piesă Spotify:
- Titlu: "{}"
- Artist: "{}"
- Album: "{}"
- Durată: {}

Rezultat YouTube:
- Titlu: "{}"
- Canal: "{}"
- Durată: {}

Analizează:
1. Titlul se potrivește? (atenție la variante, feat., remaster, etc.)
2. Artistul/canalul e corect? (VEVO, canal oficial, etc.)
3. Durația e similară? (diferență > 30s = suspect, > 60s = probabil greșit)
4. E versiunea de studio sau live/cover/remix?
5. E o compilație/mix în loc de piesă individuală?

Returnează JSON:
{{
  "quality": "high" | "medium" | "low" | "mismatch",
  "score": 85,
  "issues": ["problemă1", "problemă2"],
  "is_correct_track": true,
  "is_correct_artist": true,
  "is_studio_version": true,
  "duration_match": true,
  "recommendation": "accept" | "review" | "reject" | "re-search"
}}"#,
            spotify_title, spotify_artist, spotify_album, sp_dur,
            youtube_title, youtube_channel, yt_dur
        )
    }

