    /// I1: Smart auto-play — pick next track(s) from library based on current track
    pub fn smart_queue_next(
        current_title: &str,
        current_artist: &str,
        current_genre: Option<&str>,
        current_mood: Option<&str>,
        current_energy: Option<i32>,
        recent_track_ids: &[String],
        library_summary: &str,
        count: usize,
    ) -> String {
        let current_meta = {
            let mut parts = Vec::new();
            if let Some(g) = current_genre { parts.push(format!("Genre: {}", g)); }
            if let Some(m) = current_mood { parts.push(format!("Mood: {}", m)); }
            if let Some(e) = current_energy { parts.push(format!("Energy: {}/10", e)); }
            if parts.is_empty() { "No metadata available".to_string() }
            else { parts.join(", ") }
        };

        let recently_played = if recent_track_ids.is_empty() {
            "None".to_string()
        } else {
            format!("IDs to EXCLUDE (recently played): {:?}", recent_track_ids)
        };

        format!(
            r#"You are a smart DJ AI. The user just finished listening to a track and needs the next track(s) to play.

Currently playing: "{}" by {}
Metadata: {}
{}

Available library tracks (id | title | artist | genre | mood | energy):
{}

Select the {} best next track(s) from the library. Consider:
- Musical flow: similar genre/mood but not identical (variety!)
- Energy continuity: don't jump abruptly from 9 to 2
- Avoid recently played tracks
- Mix familiar favorites with less-played tracks

Return ONLY a JSON array of track IDs in play order:
["track-id-1", "track-id-2", ...]"#,
            current_title, current_artist, current_meta, recently_played,
            library_summary, count
        )
    }

    /// I2: Crossfade suggestion — optimal crossfade duration between two tracks
    pub fn crossfade_suggestion(
        track_a_title: &str,
        track_a_genre: Option<&str>,
        track_a_energy: Option<i32>,
        track_a_tempo: Option<&str>,
        track_b_title: &str,
        track_b_genre: Option<&str>,
        track_b_energy: Option<i32>,
        track_b_tempo: Option<&str>,
    ) -> String {
        let meta_a = format!(
            "genre={}, energy={}, tempo={}",
            track_a_genre.unwrap_or("unknown"),
            track_a_energy.map(|e| e.to_string()).unwrap_or("?".into()),
            track_a_tempo.unwrap_or("unknown")
        );
        let meta_b = format!(
            "genre={}, energy={}, tempo={}",
            track_b_genre.unwrap_or("unknown"),
            track_b_energy.map(|e| e.to_string()).unwrap_or("?".into()),
            track_b_tempo.unwrap_or("unknown")
        );

        format!(
            r#"You are a DJ mixing expert. Suggest the optimal crossfade duration between two tracks.

Track A (ending): "{}" [{}]
Track B (starting): "{}" [{}]

Rules:
- Same genre + similar tempo → short crossfade (2-4s)
- Different genres → longer crossfade (5-8s)  
- High energy to low energy → gradual crossfade (6-10s)
- Electronic/ambient → longer crossfade (8-12s)
- Rock/metal with hard endings → short or no crossfade (0-2s)

Return ONLY JSON:
{{ "duration_seconds": 5, "reason": "brief explanation" }}"#,
            track_a_title, meta_a, track_b_title, meta_b
        )
    }

