#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_enhance_search_prompt() {
        let prompt = Prompts::enhance_search("muzică pentru relaxare", &["jazz".to_string()]);
        assert!(prompt.contains("muzică pentru relaxare"));
        assert!(prompt.contains("jazz"));
    }

    #[test]
    fn test_analyze_track_prompt() {
        let prompt = Prompts::analyze_track("Enter Sandman", "Metallica");
        assert!(prompt.contains("Enter Sandman"));
        assert!(prompt.contains("Metallica"));
    }
}

